WITH latest AS (SELECT id, brand, cost, stock_qty, launch_date, tags, supplier_id FROM products QUALIFY ROW_NUMBER() OVER (PARTITION BY brand ORDER BY price ASC, id ASC) = 1) SELECT CASE WHEN cost >= 690 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_tier, supplier_id, ROUND(SUM(cost) / NULLIF(COUNT(CASE WHEN brand = 'Acme' THEN 1 END), 0), 2) AS cost_per_acme, STDDEV_SAMP(stock_qty) AS stock_qty_stddev, SORT_ARRAY(COLLECT_SET(brand)) AS brand_list FROM latest GROUP BY CASE WHEN cost >= 690 THEN 'PREMIUM' ELSE 'STANDARD' END, supplier_id ORDER BY stock_qty_stddev DESC
